// Command opencligen validates OpenCLI descriptions (https://opencli.org/)
// and generates code and documentation from them.
//
// The command line itself is described in specs/opencligen.json and
// generated by opencligen into internal/app (run "make generate"); this file
// only implements the generated Handlers. See specs/cli.md for the reference.
package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime/debug"
	"strings"

	"github.com/urfave/cli/v3"

	"github.com/angrifel/opencligen/cmd/opencligen/internal/app"
	"github.com/angrifel/opencligen/internal/gen/man"
	"github.com/angrifel/opencligen/internal/gen/markdown"
	"github.com/angrifel/opencligen/internal/gen/urfave"
	"github.com/angrifel/opencligen/internal/opencli/ast"
	"github.com/angrifel/opencligen/internal/opencli/parser"
	"github.com/angrifel/opencligen/internal/opencli/schema"
)

// Exit codes, as declared in specs/opencligen.json.
const (
	exitOK      = 0
	exitInvalid = 1 // the description has errors, or the output could not be generated
	exitUsage   = 2
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	root := app.New(&handlers{stdout: stdout, stderr: stderr})
	root.Version = fmt.Sprintf("%s (OpenCLI %s)", version(), strings.Join(schema.Versions(), ", "))
	root.Writer, root.ErrWriter = stdout, stderr
	// Exit codes are decided below, never by urfave/cli calling os.Exit.
	root.ExitErrHandler = func(context.Context, *cli.Command, error) {}
	onUsageError(root)

	err := root.Run(context.Background(), append([]string{"opencligen"}, args...))
	var inv invalidError
	switch {
	case err == nil:
		return exitOK
	case errors.As(err, &inv):
		fmt.Fprintln(stderr, inv.err)
		var se *ast.Error
		if errors.As(inv.err, &se) {
			fmt.Fprintf(stderr, "opencligen: %d error(s)\n", len(se.Diagnostics))
		}
		return exitInvalid
	default:
		// Flag parsing errors, wrong argument counts, unknown commands.
		fmt.Fprintf(stderr, "opencligen: %v\nRun \"opencligen --help\" for usage.\n", err)
		return exitUsage
	}
}

// onUsageError stops urfave/cli from printing usage errors itself, so run
// reports every error the same way.
func onUsageError(c *cli.Command) {
	c.OnUsageError = func(_ context.Context, _ *cli.Command, err error, _ bool) error { return err }
	for _, s := range c.Commands {
		onUsageError(s)
	}
}

// invalidError marks an error about the description or the generated
// output, as opposed to a usage error.
type invalidError struct{ err error }

func (e invalidError) Error() string { return e.err.Error() }

// handlers implements app.Handlers.
type handlers struct {
	stdout, stderr io.Writer
}

// load reads the SPEC argument with the global flags applied.
func (h *handlers) load(cmd *cli.Command) (*ast.Model, parser.Options, string, error) {
	opts := parser.Options{Lenient: cmd.Bool("lenient"), AllowCLimits: cmd.Bool("allow-c-limits")}
	path := cmd.Args().First()
	m, warns, err := parser.LoadFile(path, opts)
	report(h.stderr, warns)
	if err != nil {
		return nil, opts, path, invalidError{err}
	}
	return m, opts, path, nil
}

func (h *handlers) Validate(ctx context.Context, cmd *cli.Command) error {
	m, _, path, err := h.load(cmd)
	if err != nil {
		return err
	}
	fmt.Fprintf(h.stdout, "%s: valid OpenCLI %s description\n", path, m.OpenCLI)
	return nil
}

func (h *handlers) Urfave(ctx context.Context, cmd *cli.Command) error {
	m, opts, path, err := h.load(cmd)
	if err != nil {
		return err
	}
	source := cmd.String("source")
	if source == "" {
		source = filepath.ToSlash(path)
	}
	src, warns, err := urfave.Generate(m, urfave.Options{Package: cmd.String("package"), Source: source, Lenient: opts.Lenient})
	report(h.stderr, warns)
	if err != nil {
		return invalidError{err}
	}
	return h.write(cmd.String("output"), src)
}

func (h *handlers) Markdown(ctx context.Context, cmd *cli.Command) error {
	m, _, _, err := h.load(cmd)
	if err != nil {
		return err
	}
	return h.write(cmd.String("output"), markdown.Generate(m, markdown.Options{IncludeHidden: cmd.Bool("hidden")}))
}

func (h *handlers) Man(ctx context.Context, cmd *cli.Command) error {
	m, _, _, err := h.load(cmd)
	if err != nil {
		return err
	}
	page := man.Generate(m, man.Options{Section: cmd.String("section"), Date: cmd.String("date"), IncludeHidden: cmd.Bool("hidden")})
	return h.write(cmd.String("output"), page)
}

func report(w io.Writer, diags []ast.Diagnostic) {
	for _, d := range diags {
		fmt.Fprintln(w, d)
	}
}

// write writes data to path, or to standard output for "-". An existing file
// with the same content is left untouched so build tools see it as up to
// date.
func (h *handlers) write(path string, data []byte) error {
	if path == "-" {
		_, err := h.stdout.Write(data)
		return err
	}
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return invalidError{err}
	}
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return invalidError{err}
	}
	return nil
}

func version() string {
	if bi, ok := debug.ReadBuildInfo(); ok && bi.Main.Version != "" {
		return bi.Main.Version
	}
	return "(devel)"
}
